properties.query:
// Detects use of registry to create persistence in the environment
// This uses a reg key that will run on user login and could be used to call back to attacker infrastructure or run any other commands
let parent_processes = dynamic(["cmd.exe","powershell.exe"]);
let command_line = dynamic(["UserInitMprLogonScript","HKCU\\Environment","ADD"]);
_Im_ProcessCreate(parentprocess_has_any=parent_processes,commandline_has_all=command_line,targetprocess_has_any="reg.exe")
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
